(out/'README_SONG_HAU_CHI_TIET.txt').write_text('''LỚP SÔNG HẬU CHI TIẾT\n\nBản này thay lớp tham chiếu ít điểm trước đó bằng hình học chi tiết lấy từ geometry GeoJSON công bố trên WaterwayMap.org (nguồn OpenStreetMap).\n\nCác đối tượng:\n1. Sông Hậu – dòng chính trong phạm vi An Giang.\n2. Sông Châu Đốc – nhánh chính phía Bắc.\n3. Sông Bình Di – nhánh liên quan hệ thống Châu Đốc.\n4. Sông Vàm Nao – nhánh/kết nối phía khu vực Vàm Nao.\n5. Rạch Ông Chưởng – nhánh chính nối vào Sông Hậu.\n\nKhông nên mô tả lớp này trong báo cáo là “ranh giới lòng sông chính thức”.\n''',encoding='utf-8')

# package standalone shapefile
zip_path=Path('/mnt/data/SONG-HAU-CHI-TIET-OSM-WATERWAYMAP-SHAPEFILE.zip')
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED) as z:
    for ext in ['shp','shx','dbf','prj','cpg']:
        p=out/f'song_hau_detailed_osm.{ext}'
        z.write(p,p.name)
    z.write(out/'song_hau_detailed_osm_sources.txt','song_hau_detailed_osm_sources.txt')
    z.write(out/'README_SONG_HAU_CHI_TIET.txt','README_SONG_HAU_CHI_TIET.txt')
print('features',len(gdf),'points',[len(x.coords) for x in gdf.geometry])
